 private final Host host;private final MenuArt art;private final Paint p=new Paint(3);private JSONObject data;private final Map<String,JSONObject> items=new LinkedHashMap<>();private JSONArray recipes,techs;private int mode,bagPage=0,listPage=0,techPage=0,tier=0,filter=0;private String selectedRecipe="",selectedItem="",dragId="",dragKind="";private float touchX,touchY,u=1,offsetX,offsetY;private final Map<String,Integer> staged=new HashMap<>();private final ArrayDeque<String> recipeTrail=new ArrayDeque<>();private final String[] filters={"All","Food","Equipment","Components","Raw materials"};
 WorkshopView(Context c,Host h,int initial){super(c);host=h;art=MenuArt.get(c);mode=initial;try(InputStream in=c.getAssets().open("progression-data.json")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);data=new JSONObject(bytes.toString("UTF-8"));JSONArray all=data.getJSONArray("items");for(int i=0;i<all.length();i++){JSONObject item=all.getJSONObject(i);items.put(item.getString("id"),item);}recipes=data.getJSONArray("recipes");techs=data.getJSONArray("technologies");}catch(Exception e){data=new JSONObject();recipes=new JSONArray();techs=new JSONArray();}}
 private String benchStation="";
 void setStation(String station){benchStation=station;selectedRecipe="";listPage=0;staged.clear();invalidate();}
 private JSONObject bag(){JSONObject b=host.player().optJSONObject("inventory");return b==null?new JSONObject():b;}
 private int available(JSONObject r,String id){JSONObject field=host.player().optJSONObject("fieldAvailability");if(field!=null&&field.has(id))return field.optInt(id);JSONObject storage=host.craftingStorage();return bag().optInt(id)+(storage==null?0:storage.optInt(id));}
 private int rarity(String id){return Rarity.level(items.get(id));}
