 private ArrayList<String> bagIds(){ArrayList<String> ids=new ArrayList<>();JSONObject b=bag();for(String key:items.keySet())if(b.optInt(key)>0)ids.add(key);return ids;}
 private String output(JSONObject r){JSONObject out=r.optJSONObject("output");return out==null||!out.keys().hasNext()?"":out.keys().next();}
 private ArrayList<JSONObject> listing(){ArrayList<JSONObject> list=new ArrayList<>();if(mode==1){for(int i=0;i<recipes.length();i++){JSONObject r=recipes.optJSONObject(i),item=items.get(output(r));if(!r.optBoolean("acquisitionOnly")&&(benchStation.isEmpty()||benchStation.equals(r.optString("station")))&&(filter==0||item!=null&&filters[filter].equals(item.optString("category"))))list.add(r);}}else for(JSONObject item:items.values())if(!item.optBoolean("virtualIngredient")&&(filter==0||filters[filter].equals(item.optString("category"))))list.add(item);return list;}
 private JSONObject recipe(){for(int i=0;i<recipes.length();i++){JSONObject r=recipes.optJSONObject(i);if(selectedRecipe.equals(r.optString("id")))return r;}return null;}
 private boolean learned(String id){if(id.isEmpty())return true;JSONArray learned=host.player().optJSONArray("learnedTech");if(learned!=null)for(int i=0;i<learned.length();i++)if(id.equals(learned.optString(i)))return true;return id.equals("campcraft");}
 private boolean atStation(JSONObject r){JSONObject tiers=host.player().optJSONObject("stationTiers");if(r.optInt("stationTier")>0&&(tiers==null||tiers.optInt(r.optString("station"))<r.optInt("stationTier")))return false;String station=r.optString("station","");if(station.isEmpty()||station.equals("null"))return true;JSONArray list=host.stations();if(list!=null)for(int i=0;i<list.length();i++)if(station.equals(list.optString(i)))return true;return false;}
 private boolean ready(JSONObject r){if(r==null||r.optInt("constructionBenchLevel")>host.player().optInt("constructionBenchLevel")||!learned(r.optString("tech"))||!atStation(r))return false;JSONObject prof=host.player().optJSONObject("professions");if(prof==null||prof.optInt(r.optString("profession"))<r.optInt("level"))return false;JSONObject needs=r.optJSONObject("needs"),b=bag();Iterator<String> it=needs.keys();while(it.hasNext()){String k=it.next();if(available(r,k)<needs.optInt(k))return false;}return true;}
 private String blockReason(JSONObject r){if(r==null)return "Select a recipe first";if(r.optInt("constructionBenchLevel")>host.player().optInt("constructionBenchLevel"))return "Approach your construction bench level "+r.optInt("constructionBenchLevel");if(!learned(r.optString("tech")))return "Research "+techName(r.optString("tech"))+" first";if(!atStation(r))return "Requires nearby "+r.optString("station")+" tier "+Math.max(1,r.optInt("stationTier"));JSONObject prof=host.player().optJSONObject("professions");if(prof==null||prof.optInt(r.optString("profession"))<r.optInt("level"))return "Requires "+r.optString("profession")+" level "+r.optInt("level");JSONObject needs=r.optJSONObject("needs");Iterator<String> it=needs.keys();while(it.hasNext()){String k=it.next();int missing=needs.optInt(k)-available(r,k);if(missing>0)return "Need "+missing+" more "+name(k);}return "Ready to craft";}
 private boolean stagedReady(JSONObject r){if(!ready(r))return false;JSONObject needs=r.optJSONObject("needs");Iterator<String> it=needs.keys();while(it.hasNext()){String k=it.next();if(staged.getOrDefault(k,0)<needs.optInt(k))return false;}return true;}
 private void rect(Canvas c,float x,float y,float w,float h,int color){if(w>25&&h>20&&ReferenceSkin.get(getContext()).frame(c,x,y,w,h,((color>>16)&255)>((color>>8)&255)+5))return;p.setColor(color);c.drawRoundRect(x,y,x+w,y+h,7,7,p);}
 private void text(Canvas c,String s,float x,float y,float size,int color){p.setColor(color);p.setTypeface(Typeface.create(Typeface.SERIF,Typeface.NORMAL));p.setTextSize(size);c.drawText(s,x,y,p);}
 private void lines(Canvas c,String s,float x,float y,float width,int maxLines,float size,int color){p.setTypeface(Typeface.create(Typeface.SERIF,Typeface.NORMAL));p.setTextSize(size);String line="";int n=0;for(String word:s.split(" ")){String next=line.isEmpty()?word:line+" "+word;if(p.measureText(next)>width&&!line.isEmpty()){text(c,line,x,y+n*(size+3),size,color);n++;if(n>=maxLines)return;line=word;}else line=next;}if(n<maxLines)text(c,line,x,y+n*(size+3),size,color);}
