 private void mergeFieldCatalog(){JSONObject catalog=host.player().optJSONObject("fieldCatalog");if(catalog==null)return;art.mergeFieldCatalog(catalog);items.keySet().removeIf(id->id.startsWith("lot:"));JSONArray definitions=catalog.optJSONArray("items");if(definitions!=null)for(int i=0;i<definitions.length();i++){JSONObject item=definitions.optJSONObject(i);if(item!=null)items.put(item.optString("id"),item);}JSONArray extra=catalog.optJSONArray("recipes");if(extra!=null)for(int i=0;i<extra.length();i++){JSONObject r=extra.optJSONObject(i);if(r==null)continue;boolean found=false;for(int j=0;j<recipes.length();j++)if(r.optString("id").equals(recipes.optJSONObject(j).optString("id"))){found=true;break;}if(!found)recipes.put(r);}}
