 private String techName(String id){for(int i=0;i<techs.length();i++){JSONObject t=techs.optJSONObject(i);if(id.equals(t.optString("id")))return t.optString("name");}return id;}
 private ArrayList<JSONObject> tierTech(){ArrayList<JSONObject> list=new ArrayList<>();for(int i=0;i<techs.length();i++){JSONObject t=techs.optJSONObject(i);if(t.optInt("tier")==tier)list.add(t);}return list;}
 private boolean canLearn(JSONObject t){if(learned(t.optString("id"))||host.player().optInt("knowledge")<t.optInt("cost"))return false;JSONArray prereq=t.optJSONArray("requires");for(int i=0;i<prereq.length();i++)if(!learned(prereq.optString(i)))return false;return true;}
