 @Override public boolean onTouchEvent(MotionEvent e){touchX=(e.getX()-offsetX)/u;touchY=(e.getY()-offsetY)/u;float x=touchX,y=touchY;int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN){if(y>=12&&y<=48){if(x>=834){host.close();return true;}if(x>=360&&x<795){int tab=Math.min(2,(int)((x-360)/145));if(tab==0){host.inventory();return true;}mode=tab;listPage=0;invalidate();return true;}}if(y>=409&&y<=444){if(x>=28&&x<=90)bagPage=Math.max(0,bagPage-1);else if(x>=221&&x<=283)bagPage++;else if(mode!=2&&x>=330&&x<=392)listPage=Math.max(0,listPage-1);else if(mode!=2&&x>=523&&x<=585)listPage++;invalidate();return true;}if(mode==2&&y>=370&&y<=405){if(x>=330&&x<=392)techPage=Math.max(0,techPage-1);else if(x>=523&&x<=585)techPage++;invalidate();return true;}if(mode==2&&y>=99&&y<=134&&x>=328){tier=Math.max(0,Math.min(3,(int)((x-328)/153)));techPage=0;invalidate();return true;}if(mode!=2&&x>=468&&x<=616&&y>=96&&y<=125){filter=(filter+1)%filters.length;listPage=0;invalidate();return true;}if(mode==1&&x>=850&&y>=124&&y<=147&&!recipeTrail.isEmpty()){selectedRecipe=recipeTrail.pop();staged.clear();invalidate();return true;}if(mode==1&&x>=662&&x<=928&&y>=155&&y<339&&recipe()!=null){JSONObject needs=recipe().optJSONObject("needs");ArrayList<String> keys=new ArrayList<>();Iterator<String> iter=needs.keys();while(iter.hasNext())keys.add(iter.next());int slot=(int)((y-155)/46);if(slot<keys.size()){String ingredient=keys.get(slot);boolean found=false;for(int ri=0;ri<recipes.length();ri++){JSONObject child=recipes.optJSONObject(ri);if(ingredient.equals(output(child))){recipeTrail.push(selectedRecipe);selectedRecipe=child.optString("id");staged.clear();found=true;break;}}if(!found){selectedItem=ingredient;mode=0;}}invalidate();return true;}if(mode==1&&x>=662&&x<=928&&y>=445&&y<=502){JSONObject r=recipe();if(ready(r)){host.command("craft","recipe",r.optString("id"));staged.clear();}else{host.message(blockReason(r));}invalidate();return true;}
 ArrayList<String> ids=bagIds();if(x>=26&&x<293&&y>=123&&y<391){int n=bagPage*12+(int)((y-123)/67)*3+(int)((x-26)/89);if(n<ids.size()){dragId=ids.get(n);dragKind="item";selectedItem=dragId;}}else if(mode==2&&x>=328&&y>=154&&y<=367){int n=techPage*3+(int)((x-328)/205);ArrayList<JSONObject> list=tierTech();if(n<list.size()){dragId=list.get(n).optString("id");dragKind="tech";}}else if(mode!=2&&x>=328&&x<620&&y>=135&&y<395){int n=listPage*8+(int)((y-135)/65)*2+(int)((x-328)/146);ArrayList<JSONObject> list=listing();if(n<list.size()){JSONObject obj=list.get(n);if(mode==1){selectedRecipe=obj.optString("id");recipeTrail.clear();staged.clear();dragId=output(obj);dragKind="recipe";}else{selectedItem=obj.optString("id");dragId=selectedItem;dragKind="catalogue";}}}}
 else if(a==MotionEvent.ACTION_UP){if(!dragId.isEmpty()){if(dragKind.equals("item")&&x>=28&&x<=286&&y>=463&&y<=505)host.command("use","item",dragId);else if(mode==1&&dragKind.equals("item")&&x>=662&&x<=928&&y>=155&&y<339){JSONObject r=recipe();if(r!=null){JSONObject needs=r.optJSONObject("needs");ArrayList<String> keys=new ArrayList<>();Iterator<String> iterator=needs.keys();while(iterator.hasNext())keys.add(iterator.next());int n=(int)((y-155)/46);if(n<keys.size()&&keys.get(n).equals(dragId))staged.put(dragId,Math.min(needs.optInt(dragId),bag().optInt(dragId)));}}else if(mode==2&&dragKind.equals("tech")&&x>=328&&x<=932&&y>=395&&y<=495)host.command("research","tech",dragId);}dragId=dragKind="";}else if(a==MotionEvent.ACTION_CANCEL)dragId=dragKind="";invalidate();return true;}
